To convert strings to integers or floating-point numbers in Python, use `int()` and `float()`. Since invalid input raises a `ValueError`, wrap the conversion in a `try-except` block for safe execution.

### Safe Integer Conversion
```python
def safe_parse_int(value_str, default=0):
    try:
        return int(value_str.strip())
    except (ValueError, AttributeError):
        return default

print(safe_parse_int("  42  "))     # 42
print(safe_parse_int("invalid"))    # 0
print(safe_parse_int(None, -1))     # -1
```

### Safe Float Conversion
```python
def safe_parse_float(value_str, default=0.0):
    try:
        return float(value_str.strip())
    except (ValueError, AttributeError):
        return default

print(safe_parse_float("3.1415"))  # 3.1415
print(safe_parse_float("N/A"))     # 0.0
```

Using explicit exception handling avoids program crashes when processing user inputs or unstructured file data.

Python 3.9 introduced the merge (`|`) and update (`|=`) operators for dictionaries (PEP 584).

### Merge Operator `|` (Creates a New Dictionary)
```python
defaults = {"theme": "light", "notifications": True, "timeout": 30}
user_prefs = {"theme": "dark", "timeout": 60}

# Values from the right-hand dictionary take precedence
merged_config = defaults | user_prefs
print(merged_config)
# {'theme': 'dark', 'notifications': True, 'timeout': 60}
```

### Update Operator `|=` (In-place Mutation)
```python
config = {"host": "localhost", "port": 8000}
config |= {"port": 8080, "debug": True}
print(config)  # {'host': 'localhost', 'port': 8080, 'debug': True}
```

### Comparison with `dict.update()`
- `d1.update(d2)` modifies `d1` in-place and returns `None`.
- `d1 | d2` produces an entirely new dictionary leaving both `d1` and `d2` unaltered.

When dealing with complex JSON responses or nested configuration maps, querying keys like `data['user']['address']['city']` can raise a `KeyError` or `TypeError` if an intermediate key is missing or `None`.

Here is a safe getter function:

```python
def safe_get(data, keys, default=None):
    """Extract deeply nested dictionary value using a list of keys."""
    current = data
    for key in keys:
        if isinstance(current, dict):
            current = current.get(key)
            if current is None:
                return default
        else:
            return default
    return current

# Example usage
payload = {
    "account": {
        "profile": {
            "contact": {"email": "user@example.com"}
        }
    }
}

email = safe_get(payload, ["account", "profile", "contact", "email"])
print(email)  # 'user@example.com'

phone = safe_get(payload, ["account", "profile", "contact", "phone"], default="N/A")
print(phone)  # 'N/A'

missing = safe_get(payload, ["account", "settings", "theme"], default="light")
print(missing) # 'light'
```

When you decorate a function, you replace the original function with an inner `wrapper` function. Without `@functools.wraps`, the original function's introspection metadata (such as `__name__`, `__doc__`, and `__module__`) is overwritten by the wrapper's metadata.

### Without `@functools.wraps`
```python
def bad_decorator(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@bad_decorator
def greet(name):
    """Greets the person."""
    return f"Hello, {name}"

print(greet.__name__)  # 'wrapper' (Lost original function name!)
print(greet.__doc__)   # None
```

### With `@functools.wraps`
```python
from functools import wraps

def good_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@good_decorator
def greet(name):
    """Greets the person."""
    return f"Hello, {name}"

print(greet.__name__)  # 'greet' (Preserved)
print(greet.__doc__)   # 'Greets the person.' (Preserved)
```

Preserving metadata is essential for debugging, logging, documentation tools (Sphinx), and testing frameworks.

To create a decorator that accepts arguments, you need three nested function layers:
1. **Outer function**: Takes the decorator arguments.
2. **Middle function**: Takes the target function to decorate.
3. **Inner function (`wrapper`)**: Takes the arguments passed to the decorated function during execution.

### Retry Decorator Example
```python
from functools import wraps

def retry(max_attempts=3, exception_type=Exception):
    """Decorator factory that retries a function upon exception."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except exception_type as e:
                    attempts += 1
                    print(f"Attempt {attempts} failed: {e}")
                    if attempts >= max_attempts:
                        raise
        return wrapper
    return decorator

# Usage
@retry(max_attempts=3, exception_type=ConnectionError)
def fetch_remote_resource():
    # Simulating a transient failure
    raise ConnectionError("Network unreachable")
```

Here is a decorator that inspects arguments and ensures a designated argument is not empty or None before executing the wrapped function:

```python
from functools import wraps

def validate_not_empty(arg_index=0):
    """Validates that the argument at `arg_index` is non-empty."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if len(args) > arg_index and not args[arg_index]:
                raise ValueError(f"Argument at position {arg_index} cannot be empty")
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Usage
@validate_not_empty(arg_index=0)
def register_user(username, email=""):
    return f"User {username} registered successfully!"

print(register_user("Vasuki"))  # Success

try:
    register_user("")  # Raises ValueError
except ValueError as err:
    print(f"Validation caught: {err}")
```

When multiple decorators are stacked, they are applied from **bottom to top** (inside out) at definition time, and executed from **top to bottom** at call time.

### Code Example
```python
from functools import wraps

def bold(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return f"<b>{func(*args, **kwargs)}</b>"
    return wrapper

def italic(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return f"<i>{func(*args, **kwargs)}</i>"
    return wrapper

# Stacking decorators
@bold
@italic
def get_text():
    return "Hello Python"

print(get_text())
# Output: <b><i>Hello Python</i></b>
```

### Mechanics
The syntax `@bold \n @italic \n def get_text()` is syntactic sugar for:
```python
get_text = bold(italic(get_text))
```
1. First, `italic` wraps `get_text`.
2. Then, `bold` wraps the result of `italic`.
3. When invoked, `bold`'s wrapper runs first, calling `italic`'s wrapper, which calls the original function.

You can swap dictionary keys and values by iterating over `.items()` in a dictionary comprehension:

```python
original = {
    "USA": "Washington",
    "France": "Paris",
    "Japan": "Tokyo"
}

# Invert dictionary: capital becomes key, country becomes value
inverted = {capital: country for country, capital in original.items()}
print(inverted)
# {'Washington': 'USA', 'Paris': 'France', 'Tokyo': 'Japan'}
```

### Note on Duplicate Values
If the original dictionary contains duplicate values, keys in the inverted dictionary must be unique, so the last pair evaluated will overwrite earlier ones:

```python
scores = {"Alice": 100, "Bob": 95, "Charlie": 100}
# Grouping inverted duplicates safely:
inverted_grouped = {}
for name, score in scores.items():
    inverted_grouped.setdefault(score, []).append(name)
print(inverted_grouped)  # {100: ['Alice', 'Charlie'], 95: ['Bob']}
```

Custom exceptions in Python are created by subclassing the built-in `Exception` class.

### Defining a Custom Exception
```python
class ValidationError(Exception):
    """Raised when business validation rules fail."""
    def __init__(self, message, field=None, code=400):
        super().__init__(message)
        self.field = field
        self.code = code

# Raising the custom exception
def validate_age(age: int):
    if age < 0:
        raise ValidationError("Age cannot be negative", field="age", code=422)
    if age > 150:
        raise ValidationError("Age exceeds maximum human limit", field="age", code=422)
    return True

# Catching the custom exception
try:
    validate_age(-5)
except ValidationError as err:
    print(f"Validation failed on '{err.field}': {err} (HTTP {err.code})")
```

Always inherit from `Exception`, not `BaseException` (which is reserved for system-exiting exceptions like `KeyboardInterrupt` and `SystemExit`).

To re-raise the currently active exception without losing its original traceback, use a bare `raise` statement inside the `except` block:

```python
import logging

logging.basicConfig(level=logging.ERROR)

def process_payment(amount):
    try:
        if amount <= 0:
            raise ValueError("Payment amount must be greater than zero")
        return f"Processed ${amount}"
    except ValueError as e:
        # Log the incident for monitoring
        logging.error(f"Transaction failed: {e}")
        # Re-raise the exact same exception to caller
        raise

try:
    process_payment(-50)
except ValueError as e:
    print(f"Caller received exception: {e}")
```

Never use `raise e` when re-raising, as that creates a new traceback entry point instead of preserving the exact original location.

