class ETLPipeline:
    def extract(self) -> List[Dict[str, Any]]:
        # Simulated extraction from source
        return [
            {"id": 1, "price": "25.50", "status": "ACTIVE"},
            {"id": 2, "price": "-1.00", "status": "VOID"}
