    def transform(self, raw_records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        clean_records = []
        for r in raw_records:
            price = float(r["price"])
            if price >= 0 and r["status"] == "ACTIVE":
                clean_records.append({"id": r["id"], "price": price})
        return clean_records

    def load(self, data: List[Dict[str, Any]]) -> None:
        print(f"Loaded {len(data)} verified records into warehouse.")

    def run(self):
        raw = self.extract()
        clean = self.transform(raw)
        self.load(clean)

