A configuration loader pattern merging defaults, JSON config, and environment variables:

```python
import os
import json
from typing import Dict, Any

class AppConfig:
    DEFAULT_CONFIG = {
        "host": "127.0.0.1",
        "port": 8000,
        "debug": False
    }

    @classmethod
    def load(cls, config_path: str = None) -> Dict[str, Any]:
        config = cls.DEFAULT_CONFIG.copy()

        # Override with JSON file if provided
        if config_path and os.path.exists(config_path):
            with open(config_path, "r", encoding="utf-8") as f:
                config.update(json.load(f))

        # Override with environment variables if present
        if "APP_PORT" in os.environ:
            config["port"] = int(os.environ["APP_PORT"])
        if "APP_DEBUG" in os.environ:
            config["debug"] = os.environ["APP_DEBUG"].lower() == "true"

        return config
