A disk cache decorator that persists function outputs across application runs using JSON:

```python
import json
import hashlib
from functools import wraps
from pathlib import Path

def disk_cache(cache_dir="cache"):
    Path(cache_dir).mkdir(exist_ok=True)

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key_data = f"{func.__name__}:{args}:{kwargs}"
            key_hash = hashlib.sha256(key_data.encode()).hexdigest()
            cache_file = Path(cache_dir) / f"{key_hash}.json"

            if cache_file.exists():
                return json.loads(cache_file.read_text(encoding="utf-8"))

            result = func(*args, **kwargs)
            cache_file.write_text(json.dumps(result), encoding="utf-8")
            return result
        return wrapper
    return decorator

@disk_cache()
def expensive_computation(n: int):
    return {"result": sum(i for i in range(n))}

print(expensive_computation(100))
Path("cache").rmdir() if not any(Path("cache").iterdir()) else None
```

